1	//! The Remote devices dialog: who this host is to a device, where it
2	//! listens, the pairing window with its QR code, and the devices paired
3	//! so far with their scope and a Revoke. Nothing here decides anything:
4	//! every change is an action, and the host's state is read back from
5	//! the core each frame.
6	
7	use egui::{Context, RichText, Ui};
8	
9	use super::{DrawCtx, GAP, cards::since_text, theme};
10	use crate::adapters::remote;
11	use crate::core::{AppAction, AppCore};
12	use crate::ports::remote::Scope;
13	
14	/// What the dialog edits between frames: the name and port fields, the
15	/// scope the next pairing grants, and the QR image for the open code.
16	pub struct RemoteDraft {
17	    pub name: String,
18	    pub port: String,
19	    pub scope: Scope,
20	    /// The QR texture for the code it was made for.
21	    qr: Option<(String, egui::TextureHandle)>,
22	}
23	
24	impl RemoteDraft {
25	    #[must_use]
26	    pub fn open(core: &AppCore) -> Self {
27	        let identity = core.identity();
28	        Self {
29	            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
30	            port: identity
31	                .map(|i| i.listen.port.to_string())
32	                .unwrap_or_default(),
33	            scope: Scope::Read,
34	            qr: None,
35	        }
36	    }
37	}
38	
39	/// The dialog's width: the QR and the device rows fit it.
40	const DIALOG_WIDTH: f32 = 620.0;
41	/// Pixels per QR module; the quiet zone is the standard four.
42	const QR_SCALE: usize = 4;
43	const QR_QUIET: usize = 4;
44	
45	pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
46	    let Some(mut draft) = cx.state.remote_dialog.take() else {
47	        return;
48	    };
49	    let mut keep = true;
50	    egui::Window::new("")
51	        .id(egui::Id::new("remote-devices"))
52	        .title_bar(false)
53	        .collapsible(false)
54	        .resizable(true)
55	        .default_width(DIALOG_WIDTH)
56	        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
57	        .show(ctx, |ui| {
58	            let screen = ctx.content_rect().width();
59	            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
60	            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
61	            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
62	            ui.add_space(8.0);
63	            host(cx, ui, &mut draft);
64	            ui.add_space(8.0);
65	            pairing(cx, ui, &mut draft);
66	            ui.add_space(8.0);
67	            devices(cx, ui);
68	            ui.add_space(8.0);
69	            let p = theme::palette(ui);
70	            ui.label(
71	                RichText::new(
72	                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
73	                )
74	                .small()
75	                .color(p.n600),
76	            );
77	            ui.horizontal(|ui| {
78	                if theme::ghost_muted(ui, "Close").clicked() {
79	                    keep = false;
80	                }
81	            });
82	        });
83	    if keep {
84	        cx.state.remote_dialog = Some(draft);
85	    }
86	}
