/// The value of the cookie called `name` in a `Cookie` header, matched
/// by exact name; every other cookie is ignored.
#[must_use]
pub fn cookie_value(header: &str, name: &str) -> Option<String> {
    header.split(';').find_map(|pair| {
        let (n, v) = pair.trim().split_once('=')?;
        (n.trim() == name).then(|| v.trim().to_owned())
    })
}

