/* The web control surface: one column, large touch targets, the
   waiting mark in words as well as colour. Light and dark follow the
   phone. */

:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #6b6b6b;
  --line: #e2e2e2;
  --card: #f6f6f6;
  --waiting: #b35c00;
  --waiting-bg: #fff3e6;
  --accent: #2d5bd1;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #121212;
    --fg: #ececec;
    --muted: #9a9a9a;
    --line: #2c2c2c;
    --card: #1c1c1c;
    --waiting: #ffb366;
    --waiting-bg: #2a1d0f;
    --accent: #7fa3ff;
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

#top {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: var(--bg);
}

#host-name { font-weight: 600; flex: 1; }
#scope { color: var(--muted); font-size: 14px; }

main { padding: 12px 16px 32px; }

button {
  font: inherit;
  color: var(--fg);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 14px;
  min-height: 44px;
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

button:disabled { opacity: 0.5; }

h2 {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin: 20px 0 8px;
}

.row {
  display: block;
  width: 100%;
  text-align: left;
  margin-bottom: 8px;
  padding: 12px 14px;
}

.row.waiting {
  border-color: var(--waiting);
  background: var(--waiting-bg);
}

.row .name { font-weight: 600; display: block; }
.row .meta { color: var(--muted); font-size: 14px; display: block; }
.row .mark { color: var(--waiting); font-weight: 600; font-size: 14px; display: block; }

.notice {
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  margin-bottom: 12px;
}

.notice.error { border-color: var(--waiting); }

pre.text {
  white-space: pre-wrap;
  word-break: break-word;
  font: 14px/1.4 ui-monospace, Menlo, monospace;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  margin: 0 0 12px;
  max-height: 60vh;
  overflow: auto;
}

.compose { display: flex; flex-direction: column; gap: 8px; }

textarea {
  font: inherit;
  color: var(--fg);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  min-height: 88px;
  width: 100%;
  resize: vertical;
}

.status { color: var(--muted); font-size: 14px; min-height: 1.4em; }

p.small { color: var(--muted); font-size: 14px; }

