        matches!(&e[0], Effect::Save(w) if w.sessions[0].last_seen == output),
        "{e:?}"
    );
    assert!(matches!(&e[1], Effect::Kill(h) if h.0 == id.host_name()));
    assert_eq!(spawns(&e).len(), 1);
    assert!(core.session(id).unwrap().last_seen >= output);
}

