//! UI tests: the real `eframe::App` headlessly via `egui_kittest` with
//! fake adapters. State is seeded directly (the core's `dispatch` is
//! exercised by the core tests), the widgets are found by label, and the
//! assertions are on what is drawn and which actions a click dispatched.

// Tests assert emptiness with `assert!` throughout.
#![allow(clippy::assert_is_empty)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use egui::accesskit::Role;
use egui_kittest::Harness;
use egui_kittest::kittest::{NodeT, Queryable};
use switchboard::SwitchboardApp;
use switchboard::adapters::fakes::{
    self, FakeChanges, FakeDispatch, FakeHost, FakeOpener, FakeSecrets, FakeTranscripts,
    MemoryStore,
};
use switchboard::app::Services;
use switchboard::core::{
    Activity, AgentKind, AppAction, Approval, Ask, AskKind, BUILTIN_WORKFLOW, CardLayout,
    CardState, Composer, ControlAction, Definition, HandoffMode, Launch, Notice, PinTarget,
    Project, ProjectEnv, ProjectId, RecordId, ResumeHandle, Round, RunState, SessionKind,
    SessionRecord, SideTab, SpaceId, StopPending, ThemeMode, Verdict, View, VoiceSettings, Wakeup,
    WorkflowDefinition, WorkflowId, WorkflowRun, Workspace, round_paths,
};
use switchboard::ports::changes::{Changes, Commit, FileStat};
use switchboard::ports::events::{EventKind, SessionEvent};
use switchboard::ports::host::{HostId, HostStatus, Liveness};
use switchboard::ports::store::Store;
use switchboard::ports::transcript::{
    Activity as TranscriptActivity, ActivityKind, Conversation, ToolDetail, Turn, Usage,
};
use switchboard::ui::working_set;

/// Ids of the seeded records, so tests can name them in assertions.
struct Seeded {
    alpha: ProjectId,
    beta: ProjectId,
    build: RecordId,
    server: RecordId,
    deploy: RecordId,
    agent: RecordId,
    /// A command defined in alpha's `.switchboard/project.json`, unapproved.
    lint: RecordId,
}

fn at(secs: u64) -> SystemTime {
    UNIX_EPOCH + Duration::from_secs(1_700_000_000 + secs)
}

fn project(name: &str, last_active: SystemTime) -> Project {
    Project {
        id: ProjectId::new(),
        name: name.into(),
        root: PathBuf::from(format!("/work/{name}")),
        tags: Vec::new(),
        notes: format!("notes for {name}"),
        pinned: vec![PathBuf::from("README.md")],
        env: ProjectEnv::default(),
        shown: Vec::new(),
        created: at(0),
        last_active,
        space: SpaceId::DEFAULT,
        op: None,
        env_sets: Vec::new(),
    }
}

fn record(project: ProjectId, name: &str, kind: SessionKind, order: u32) -> SessionRecord {
    SessionRecord {
        id: RecordId::new(),
        project,
        name: name.into(),
        kind,
        cwd: PathBuf::from(format!("/work/{name}")),
        launch: Launch::Shell,
        env_profile: None,
        created: at(0),
        last_seen: at(0),
        notes: String::new(),
        resume: None,
        autostart: false,
        layout: CardLayout { order, group: None },
        activity: Activity::Unknown,
        activity_reason: None,
        last_event_at: None,
        last_exit: None,
        not_resumable: false,
        scrollback: None,
        source: None,
        approved_hash: None,
        discard: None,
        runs: Vec::new(),
        outputs: Vec::new(),
        op: None,
        waiting_on: None,
        pending_launch: false,
        last_stop_at: None,
        pending_at_stop: None,
        env: Vec::new(),
        env_sets: Vec::new(),
        token_hash: None,
        asking: None,
    }
}

/// Two projects. `alpha` (most recent) has a session that is not running,
/// one running, and one exited; `beta` has one agent session.
fn seed(app: &mut SwitchboardApp) -> Seeded {
    let alpha = project("alpha", at(100));
    let beta = project("beta", at(50));
    let build = record(alpha.id, "build", SessionKind::Command, 0);
    let mut server = record(alpha.id, "server", SessionKind::Shell, 1);
    server.activity = Activity::WaitingOnYou;
    server.activity_reason = Some("permission for Bash".into());
    let deploy = record(alpha.id, "deploy", SessionKind::Service, 2);
    let mut lint = record(alpha.id, "lint", SessionKind::Command, 3);
    lint.launch = Launch::Command {
        command: "cargo clippy".into(),
        shell: "/bin/zsh".into(),
    };
    lint.source = Some(Definition {
        name: "lint".into(),
        hash: "h1".into(),
        env: vec!["RUSTFLAGS".into()],
        autostart: false,
        orphaned: false,
    });
    let agent = record(
        beta.id,
        "codex-agent",
        SessionKind::Agent(AgentKind::Codex),
        0,
    );
    let ids = Seeded {
        alpha: alpha.id,
        beta: beta.id,
        build: build.id,
        server: server.id,
        deploy: deploy.id,
        agent: agent.id,
        lint: lint.id,
    };
    let host = vec![
        HostStatus {
            id: HostId(server.id.host_name()),
            liveness: Liveness::Running {
                pid: 42,
                command: "zsh".into(),
            },
            cwd: None,
            last_activity: None,
            title: Some("make: all".into()),
        },
        HostStatus {
            id: HostId(deploy.id.host_name()),
            liveness: Liveness::Exited { code: Some(1) },
            cwd: None,
            last_activity: None,
            title: None,
        },
    ];
    let mut alpha_ws = Workspace::new(alpha);
    alpha_ws.sessions = vec![build, server, deploy, lint];
    let mut beta_ws = Workspace::new(beta);
    beta_ws.sessions = vec![agent];
    app.core_mut_for_seeding()
        .seed(vec![alpha_ws, beta_ws], host);
    ids
}

fn harness() -> (Harness<'static, SwitchboardApp>, Seeded) {
    harness_with(FakeOpener::default())
}

/// A harness whose opener the test keeps a handle to.
fn harness_with(opener: FakeOpener) -> (Harness<'static, SwitchboardApp>, Seeded) {
    harness_build(opener, FakeSecrets::default(), FakeHost::default())
}

/// A harness on these fakes, which the test keeps handles to.
fn harness_build(
    opener: FakeOpener,
    secrets: FakeSecrets,
    host: FakeHost,
) -> (Harness<'static, SwitchboardApp>, Seeded) {
    harness_on(fake_services(opener, secrets, host))
}

/// A seeded harness on these services.
fn harness_on(services: Services) -> (Harness<'static, SwitchboardApp>, Seeded) {
    harness_sized(services, egui::vec2(1200.0, 900.0))
}

/// `harness_on` with a window of `size`.
fn harness_sized(
    services: Services,
    size: egui::Vec2,
) -> (Harness<'static, SwitchboardApp>, Seeded) {
    let mut harness = Harness::builder().with_size(size).build_eframe(move |cc| {
        switchboard::ui::theme::install(&cc.egui_ctx);
        test_app(services)
    });
    let ids = seed(harness.state_mut());
    harness.run_steps(2);
    (harness, ids)
}

fn fake_services(opener: FakeOpener, secrets: FakeSecrets, host: FakeHost) -> Services {
    Services {
        host: std::sync::Arc::new(host),
        opener: Box::new(opener),
        secrets: std::sync::Arc::new(secrets),
        ..fakes::services()
    }
}

/// The app as every harness drives it: actions recorded, no embedded
/// terminals, no native prompt box, no speech model.
fn test_app(services: Services) -> SwitchboardApp {
    let mut app = SwitchboardApp::with_services(services);
    app.record_actions = true;
    app.ui_state.embed_terminals = false;
    app.ui_state.prompt_boxes.native = false;
    // No speech model in tests: the demo stands in for the
    // microphone. A real model on the developer's machine would
    // otherwise be loaded onto the GPU by every listening test at
    // once, and whisper's Metal setup aborts on that race.
    app.ui_state.prompt_boxes.voice =
        promptbox::Voice::new(std::path::PathBuf::from("/nonexistent/ggml-none.bin"));
    app
}

/// Turns the Prompt Box editor off so the plain message box is drawn.
fn plain_message_box(harness: &mut Harness<'static, SwitchboardApp>) {
    harness.state_mut().dispatch(AppAction::SetPromptBox(false));
    harness.state_mut().dispatched.clear();
}

fn showing(harness: &mut Harness<'static, SwitchboardApp>, view: View) {
    harness.state_mut().core_mut_for_seeding().seed_view(view);
    harness.run_steps(2);
}

/// Every action a test's clicks dispatched, without the per-frame ticks.
fn actions(harness: &Harness<'static, SwitchboardApp>) -> Vec<AppAction> {
    harness
        .state()
        .dispatched
        .iter()
        .filter(|a| **a != AppAction::Tick)
        .cloned()
        .collect()
}

/// Runs frames until `ready`, for state that lands from a thread;
/// panics naming `what` after ten seconds.
fn frames_until(
    harness: &mut Harness<'static, SwitchboardApp>,
    what: &str,
    mut ready: impl FnMut(&Harness<'static, SwitchboardApp>) -> bool,
) {
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        harness.run_steps(2);
        if ready(harness) {
            return;
        }
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        std::thread::sleep(Duration::from_millis(25));
    }
}

fn click(harness: &mut Harness<'static, SwitchboardApp>, label: &str) {
    harness.get_by_label(label).click();
    harness.run_steps(2);
}

#[test]
fn settings_menu_sets_the_theme() {
    let (mut harness, _) = harness();
    click(&mut harness, "Settings");
    click(&mut harness, "Dark");
    assert!(actions(&harness).contains(&AppAction::SetTheme(ThemeMode::Dark)));
    assert_eq!(harness.state().core().settings().theme, ThemeMode::Dark);
}

#[test]
fn the_rail_offers_a_newer_release_and_the_settings_menu_names_the_version() {
    let (mut harness, _) = harness();
    assert_eq!(harness.query_all_by_label("Update ↑").count(), 0);
    let release = switchboard::ports::updates::Release {
        version: "9.9.9".into(),
        notes: String::new(),
        asset_url: "https://x/Switchboard.zip".into(),
        asset_name: "Switchboard.zip".into(),
        digest_url: None,
    };
    harness
        .state_mut()
        .dispatch(AppAction::UpdateChecked(Ok(Some(release))));
    harness.run_steps(2);
    click(&mut harness, "Update ↑");
    assert!(actions(&harness).contains(&AppAction::DownloadUpdate));
    // The fake's download runs on a thread, so by now the release is
    // either still downloading or already staged.
    assert!(matches!(
        harness.state().core().update(),
        switchboard::core::updates::UpdateState::Downloading(r)
        | switchboard::core::updates::UpdateState::Ready { release: r, .. } if r.version == "9.9.9"
    ));
    click(&mut harness, "Settings");
    harness.get_by_label(format!("Switchboard {}", env!("CARGO_PKG_VERSION")).as_str());
}

#[test]
fn a_new_workspace_shows_nothing_of_the_others_until_the_selector_opens() {
    let (mut harness, _) = harness();
    assert!(harness.query_all_by_label("beta").count() > 0);
    // The rail's head names the active workspace and opens the selector.
    click(&mut harness, "Default ▾");
    click(&mut harness, "New workspace…");
    harness.get_by_label("New workspace");
    type_into(&mut harness, "Name", "Client");
    click(&mut harness, "Create");
    assert!(
        actions(&harness).contains(&AppAction::NewSpace("Client".into())),
        "{:?}",
        actions(&harness)
    );
    harness.get_by_label("Client ▾");
    // Nothing of the default workspace is on screen: no project names,
    // no rows, and the quick switcher finds none of them.
    assert_eq!(harness.query_all_by_label("alpha").count(), 0);
    assert_eq!(harness.query_all_by_label("beta").count(), 0);
    assert_eq!(harness.query_all_by_label("Default").count(), 0);
    click(&mut harness, "Go to ⌘K");
    assert_eq!(harness.query_all_by_label_contains("alpha").count(), 0);
    click(&mut harness, "All workspaces");
    harness.get_by_label("Default · alpha");
    harness.key_press(egui::Key::Escape);
    harness.run_steps(2);
    // A notice about the default workspace's session says only that
    // something needs attention.
    harness.state_mut().core_mut_for_seeding().seed_status(
        Some(Notice {
            text: "cannot start server: gone".into(),
            is_error: true,
            expires_at: None,
            space: Some(SpaceId::DEFAULT),
            undo: None,
        }),
        None,
        false,
    );
    harness.run_steps(2);
    harness.get_by_label(Notice::ELSEWHERE);
    assert_eq!(harness.query_all_by_label_contains("server").count(), 0);
    // The selector lists every workspace; picking one steps into it.
    click(&mut harness, "Client ▾");
    // The row carries the workspace's waiting count: a number only.
    harness.get_by_label_contains("Default 1").click();
    harness.run_steps(2);
    assert!(actions(&harness).contains(&AppAction::ShowSpace(SpaceId::DEFAULT)));
    harness.get_by_label("Default ▾");
    assert!(harness.query_all_by_label("alpha").count() > 0);
    harness.get_by_label("cannot start server: gone");
}

/// The seed split over two workspaces: `alpha` stays in Default, `beta`
/// moves to "Client", and beta's agent runs waiting on the user, so each
/// workspace has one waiting session. Nothing is made active here.
fn two_workspaces(harness: &mut Harness<'static, SwitchboardApp>, ids: &Seeded) -> SpaceId {
    let clock = switchboard::core::Clock::at(1);
    let core = harness.state_mut().core_mut_for_seeding();
    core.dispatch(AppAction::NewSpace("Client".into()), clock);
    let client = core.spaces()[1].id;
    core.dispatch(AppAction::MoveProjectToSpace(ids.beta, client), clock);
    core.dispatch(AppAction::ShowSpace(SpaceId::DEFAULT), clock);
    let mut workspaces = core.workspaces().to_vec();
    let mut host: Vec<HostStatus> = workspaces
        .iter()
        .flat_map(|w| &w.sessions)
        .filter_map(|s| core.host_status(s.id).cloned())
        .collect();
    for w in &mut workspaces {
        for s in &mut w.sessions {
            if s.id == ids.agent {
                s.activity = Activity::WaitingOnYou;
            }
        }
    }
    host.push(HostStatus {
        id: HostId(ids.agent.host_name()),
        liveness: Liveness::Running {
            pid: 43,
            command: "codex".into(),
        },
        cwd: None,
        last_activity: None,
        title: None,
    });
    core.seed(workspaces, host);
    harness.run_steps(2);
    client
}

fn show_global(harness: &mut Harness<'static, SwitchboardApp>) {
    harness.state_mut().core_mut_for_seeding().dispatch(
        AppAction::ShowSpace(SpaceId::GLOBAL),
        switchboard::core::Clock::at(2),
    );
    harness.run_steps(2);
}

