/// A Claude Code session, running, with a resume handle: the shape the
/// conversation view needs. Added on top of the standard seed.
fn seed_claude(harness: &mut Harness<'static, SwitchboardApp>, ids: &Seeded) -> RecordId {
    seed_claude_at(harness, ids, None)
}

/// [`seed_claude`], working in `cwd` when one is given.
fn seed_claude_at(
    harness: &mut Harness<'static, SwitchboardApp>,
    ids: &Seeded,
    cwd: Option<PathBuf>,
) -> RecordId {
    let mut claude = record(
        ids.beta,
        "claude-agent",
        SessionKind::Agent(AgentKind::ClaudeCode),
        1,
    );
    claude.resume = Some(ResumeHandle::ClaudeCode {
        session_id: uuid::Uuid::nil(),
        transcript: Some(PathBuf::from("/nowhere/x.jsonl")),
    });
    if let Some(cwd) = cwd {
        claude.cwd = cwd;
    }
    let id = claude.id;
    let core = harness.state_mut().core_mut_for_seeding();
    let mut workspaces = core.workspaces().to_vec();
    workspaces
        .iter_mut()
        .find(|w| w.project.id == ids.beta)
        .unwrap()
        .sessions
        .push(claude);
    let host = vec![HostStatus {
        id: HostId(id.host_name()),
        liveness: Liveness::Running {
            pid: 43,
            command: "claude".into(),
        },
        cwd: None,
        last_activity: None,
        title: None,
    }];
    core.seed(workspaces, host);
    id
}

/// Mark `id` as asking the owner `message`, as `switchboard-ask` would,
/// keeping every pane's status as it was.
fn seed_ask(harness: &mut Harness<'static, SwitchboardApp>, id: RecordId, message: &str) {
    seed_ask_with(harness, id, message, |_| {});
}

/// An ask that a permission prompt blocks the pane on top of.
fn seed_blocked_ask(harness: &mut Harness<'static, SwitchboardApp>, id: RecordId, message: &str) {
    seed_ask_with(harness, id, message, |s| {
        s.activity = Activity::WaitingOnYou;
        s.activity_reason = Some("permission for Bash".into());
    });
}

fn seed_ask_with(
    harness: &mut Harness<'static, SwitchboardApp>,
    id: RecordId,
    message: &str,
    edit: impl FnOnce(&mut SessionRecord),
) {
    let core = harness.state_mut().core_mut_for_seeding();
    let mut workspaces = core.workspaces().to_vec();
    let host: Vec<HostStatus> = workspaces
        .iter()
        .flat_map(|w| &w.sessions)
        .filter_map(|s| core.host_status(s.id).cloned())
        .collect();
    workspaces
        .iter_mut()
        .flat_map(|w| &mut w.sessions)
        .find(|s| s.id == id)
        .map(|s| {
            s.asking = Some(Ask::note(message, SystemTime::now()));
            edit(s);
        })
        .unwrap();
    core.seed(workspaces, host);
    harness.run_steps(2);
}

