        path: path.clone(),
        line: Some(400),
    });
    harness.run_steps(SCROLLED);
    let scrolled = top(&harness);
    assert!(scrolled < at_top - 1000.0, "{at_top} -> {scrolled}");
    // The same file from the tree drops the line, and its scroll.
    harness
        .state_mut()
        .dispatch(AppAction::ShowDocument(pid, path.clone()));
