        assert_eq!(saved.devices.len(), 1);
        assert_eq!(saved.devices[0].name, "Vision Pro");
        assert_eq!(saved.devices[0].scope, Scope::Read);
        assert_eq!(saved.devices[0].token_sha256, remote::token_sha256(&token));
