    assert_eq!(status, 200, "{reply}");
    assert!(reply["body"]["sessions"].is_array());
    let (status, reply) = get(&mut port, &format!("/api/v1/sessions/{session}/screen"), t);
    assert_eq!(
        (status, code(&reply)),
