    let tickets = read("tickets");
    assert_eq!(tickets["body"]["connected"], true);
    assert_eq!(tickets["body"]["tickets"][0]["id"], "t1");
    assert_eq!(
        tickets["body"]["tickets"][0]["decisions"][0]["name"],
