        resources(&got),
        vec![("changed".into(), "run_output".into(), key.id())]
    );
    assert!(got[0]["revision"].as_u64().unwrap() > first);
    let (_, out) = get(
        &mut port,
        &format!("/api/v1/sessions/{session}/runs/1/output?lines=1"),
        t,
    );
    assert_eq!(out["body"]["text"], "done");
}

