/// The ids of the `session` frames a subscriber got.
fn session_frames(port: &mut Port, s: &Subscriber) -> Vec<String> {
    resources(&events(port, s))
        .into_iter()
        .filter(|(_, kind, _)| kind == "session")
        .map(|(_, _, id)| id)
        .collect()
}

