/// One HTTP request over a fresh pinned TLS connection: the status and
/// the body.
fn http(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    method: &str,
    path: &str,
    bearer: Option<&str>,
    body: &str,
) -> std::io::Result<(u16, String)> {
    let auth = bearer.map(|t| format!("Bearer {t}"));
    let headers: Vec<(&str, &str)> = auth
        .as_deref()
        .map(|a| vec![("Authorization", a)])
        .unwrap_or_default();
    http_with(addr, config, method, path, &headers, body).map(|r| (r.status, r.body))
}

/// A reply whole: the status, the headers as sent (names lowercased),
/// and the body.
#[derive(Debug)]
struct Response {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

impl Response {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, v)| v.as_str())
    }

    fn json(&self) -> serde_json::Value {
        serde_json::from_str(&self.body).unwrap_or_else(|e| panic!("{e}: {}", self.body))
    }
}

/// One HTTP request with these headers over a fresh pinned TLS
/// connection, the whole reply back. `Host` is always `localhost`, so a
/// browser's `Origin` for this page would be `https://localhost`.
fn http_with(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    method: &str,
    path: &str,
    headers: &[(&str, &str)],
    body: &str,
) -> std::io::Result<Response> {
    let tcp = TcpStream::connect(addr)?;
    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
    let conn = ClientConnection::new(
        Arc::clone(config),
        ServerName::try_from("localhost").unwrap(),
    )
    .map_err(std::io::Error::other)?;
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock)?;
    }
    let extra: String = headers
        .iter()
        .map(|(n, v)| format!("{n}: {v}\r\n"))
        .collect();
    write!(
        s,
        "{method} {path} HTTP/1.1\r\nHost: localhost\r\n{extra}Content-Length: {}\r\n\r\n{body}",
        body.len()
    )?;
    s.flush()?;
    let mut reader = BufReader::new(s);
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let status: u16 = line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
    let mut length = 0usize;
    let mut headers = Vec::new();
    loop {
        let mut h = String::new();
        reader.read_line(&mut h)?;
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some((n, v)) = h.split_once(':') {
            let (n, v) = (n.trim().to_ascii_lowercase(), v.trim().to_owned());
            if n == "content-length" {
                length = v.parse().unwrap_or(0);
            }
            headers.push((n, v));
        }
    }
    let mut out = vec![0; length];
    reader.read_exact(&mut out)?;
    Ok(Response {
        status,
        headers,
        body: String::from_utf8_lossy(&out).into_owned(),
    })
}

/// A request with headers from a client thread, served by the app on
/// this thread; the whole reply.
fn call_with(
    port: &mut Port,
    method: &str,
    path: &str,
    headers: &[(&str, &str)],
    body: &str,
) -> Response {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let (method, path, body) = (method.to_owned(), path.to_owned(), body.to_owned());
    let headers: Vec<(String, String)> = headers
        .iter()
        .map(|(n, v)| ((*n).to_owned(), (*v).to_owned()))
        .collect();
    let client = std::thread::spawn(move || {
        let borrowed: Vec<(&str, &str)> = headers
            .iter()
            .map(|(n, v)| (n.as_str(), v.as_str()))
            .collect();
        http_with(addr, &config, &method, &path, &borrowed, &body)
    });
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap().expect("http")
}

/// A request from a client thread, served by the app on this thread.
fn call(
    port: &mut Port,
    method: &str,
    path: &str,
    bearer: Option<&str>,
    body: &str,
) -> (u16, serde_json::Value) {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let (method, path, bearer, body) = (
        method.to_owned(),
        path.to_owned(),
        bearer.map(str::to_owned),
        body.to_owned(),
    );
    let client =
        std::thread::spawn(move || http(addr, &config, &method, &path, bearer.as_deref(), &body));
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    let (status, text) = client.join().unwrap().expect("http");
    let value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{e}: {text}"));
    (status, value)
}

fn get(port: &mut Port, path: &str, bearer: Option<&str>) -> (u16, serde_json::Value) {
    call(port, "GET", path, bearer, "")
}

/// The error code of a refusal.
fn code(value: &serde_json::Value) -> &str {
    value["error"]["code"].as_str().unwrap_or("")
}

/// One call on the control socket, for making records.
fn control(port: &mut Port, request: Request) -> Reply {
    let path = port.control.clone();
    let client = std::thread::spawn(move || {
        let mut client = Client::connect(&path).expect("connect");
        client.call(&request).expect("reply")
    });
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap()
}

fn made_id(reply: &Reply, kind: RecordKind) -> String {
    reply
        .made()
        .iter()
        .find(|m: &&Made| m.kind == kind)
        .unwrap_or_else(|| panic!("no {kind:?} in {reply:?}"))
        .id
        .clone()
}

/// A space, a project in it, and a session in that, with `notes`.
fn seed(port: &mut Port, notes: &str) -> (String, String, String) {
    let reply = control(
        port,
        Request::new("sp", Body::SpaceNew { name: "D".into() }),
    );
    let space = made_id(&reply, RecordKind::Space);
    let reply = control(
        port,
        Request::new(
            "pj",
            Body::ProjectAdd {
                space: space.clone(),
                name: "#1".into(),
                root: PathBuf::from("/tmp"),
            },
        ),
    );
    let project = made_id(&reply, RecordKind::Project);
    let reply = control(
        port,
        Request::new(
            "se",
            Body::SessionNew {
                project: project.clone(),
                name: "investigator".into(),
                session_kind: SessionKind::Claude,
                cwd: PathBuf::from("/tmp"),
                launch: Launch::Shell,
                prompt: None,
                notes: notes.into(),
                env: std::collections::BTreeMap::new(),
                env_sets: Vec::new(),
                replaces: None,
            },
        ),
    );
    let session = made_id(&reply, RecordKind::Session);
    // The host lists no pane for it: a session that is not running.
    port.app.poll_now();
    (space, project, session)
}

/// Open the pairing window with `code` and pair as `name`: the token.
fn pair(port: &mut Port, code: &str, scope: Scope, name: &str) -> String {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    let body = serde_json::json!({ "code": code, "device_name": name, "spki_sha256": spki });
    let (status, reply) = call(port, "POST", "/api/v1/pair", None, &body.to_string());
    assert_eq!(status, 200, "{reply}");
    reply["body"]["token"].as_str().unwrap().to_owned()
}

/// What a browser's pairing left it: the cookie's name and value, and
/// the device id the reply named.
struct Cookie {
    name: String,
    token: String,
    device_id: String,
}

impl Cookie {
    /// The `Cookie` header's value for this one.
    fn pair(&self) -> String {
        format!("{}={}", self.name, self.token)
    }
}

/// Pair as the page does: `/pair` with `transport: "cookie"`, the token
/// taken from `Set-Cookie` and never from the body.
fn pair_by_cookie(port: &mut Port, code: &str, scope: Scope, name: &str) -> Cookie {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    let body = serde_json::json!({
        "code": code, "device_name": name, "spki_sha256": spki, "transport": "cookie",
    });
    let r = call_with(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(r.status, 200, "{}", r.body);
    let reply = r.json();
    assert!(
        reply["body"].get("token").is_none(),
        "no token in the body: {reply}"
    );
    let set_cookie = r.header("set-cookie").expect("Set-Cookie");
    let (pair, _) = set_cookie.split_once(';').unwrap();
    let (name, token) = pair.split_once('=').unwrap();
    Cookie {
        name: name.to_owned(),
        token: token.to_owned(),
        device_id: reply["body"]["device_id"].as_str().unwrap().to_owned(),
    }
}

#[test]
fn info_is_served_to_anyone_and_every_other_read_is_refused_unpaired() {
    let mut port = port();
    let (status, info) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200, "{info}");
    let identity = port.remote.state().identity.clone().unwrap();
    let body = &info["body"];
    assert_eq!(body["server_id"], identity.server_id.to_string());
    assert_eq!(body["server_name"], identity.server_name);
    assert_eq!(body["spki_sha256"], identity.spki_sha256);
    assert_eq!(body["protocol"], 1);
    assert_eq!(body["pairing_open"], false);
    assert_eq!(body["limits"]["screen_lines"], 200);
    assert!(info["epoch"].is_string());
    assert_eq!(info["revision"], 0);
    assert!(
        !info.to_string().contains("remote-key"),
        "no key material in /info"
    );

    for path in [
        "/api/v1/projects",
        "/api/v1/spaces",
        "/api/v1/waiting",
        "/api/v1/sessions/x",
    ] {
        let (status, reply) = get(&mut port, path, None);
        assert_eq!(
            (status, code(&reply)),
            (401, "unauthorized"),
            "{path}: {reply}"
        );
