}

#[test]
fn a_pairing_inside_the_window_gives_a_token_that_reads_every_view() {
    let mut port = port();
    let (space, project, session) = seed(&mut port, "ticket 1");
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Vision Pro");
    assert_eq!(token.len(), 43);
