    assert_eq!(status, 200, "{reply}");
    assert!(
        reply["body"]["spaces"]
            .as_array()
            .unwrap()
            .iter()
            .any(|s| s["id"] == space)
    );
    let (status, reply) = get(&mut port, &format!("/api/v1/spaces/{space}/sets"), t);
    assert_eq!(status, 200, "{reply}");
    assert!(reply["body"]["sets"].is_array());
    let (status, reply) = get(
