            .dispatch(AppAction::RenameSession(record, name.into()));
    }
    let heard = resources(&events(&mut port, &plain));
    assert!(
        !heard
            .iter()
            .any(|(_, kind, id)| kind == "sessions" && id == &ticket),
        "no frame about the ticket project's collection: {heard:?}"
    );
