        !plain_ids.contains(&reviewer) && !plain_ids.contains(&planner),
        "{plain_ids:?}"
    );
    let all_ids = session_frames(&mut port, &all);
    assert!(
        all_ids.contains(&reviewer) && all_ids.contains(&planner),
