    func testInviteParsesTheQRText() throws {
        // The host's QR and "Copy invite" carry the web page's URL, with
        // the code, the key and the id in the fragment.
        let url = "https://192.168.1.9:43187/#code=abcd2345&key=AB&id=17A9B824-AC51-47DC-A96A-C2B9E69C85B4"
        let invite = try PairingInvite.parse(url)
        XCTAssertEqual(invite.serverID.raw, "17a9b824-ac51-47dc-a96a-c2b9e69c85b4")
        XCTAssertEqual(invite.serverID.short, "17a9b8")
        XCTAssertEqual(invite.spkiSha256, "ab")
        XCTAssertEqual(invite.code, "ABCD2345")
        XCTAssertEqual(invite.addresses, ["192.168.1.9:43187"])
        // An older host's JSON form parses to the same invite.
        let text = """
            {"server_id":"17A9B824-AC51-47DC-A96A-C2B9E69C85B4","spki_sha256":"ab","code":"ABCD2345","addresses":["192.168.1.9:43187"]}
            """
        XCTAssertEqual(try PairingInvite.parse(text), invite)
        // A URL without the code is an error, as malformed JSON is.
        XCTAssertThrowsError(try PairingInvite.parse("https://192.168.1.9:43187/#key=ab&id=x"))
        XCTAssertThrowsError(try PairingInvite.parse("https://192.168.1.9:43187/"))
        XCTAssertThrowsError(try PairingInvite.parse("{not json"))
        // Pasted with a trailing newline, and an IPv6 address in brackets.
        let six = try PairingInvite.parse("https://[fe80::1]:1/#code=ABCD2345&key=ab&id=x\n")
        XCTAssertEqual(six.addresses, ["[fe80::1]:1"])
    }
}

