import Foundation

/// What `/info` says to anyone.
public struct ServerInfo: Decodable, Sendable, Equatable {
    public let serverID: ServerID
    public let serverName: String
    public let protocolVersion: Int
    public let capabilities: [String]
    public let spkiSha256: String
    public let limits: Limits
    public let pairingOpen: Bool
    /// The host app's version; a host older than this field has none.
    public let version: String?

    public struct Limits: Decodable, Sendable, Equatable {
        public let bodyBytes: Int
        public let stringBytes: Int
        public let notesBytes: Int
        public let screenLines: Int

        enum CodingKeys: String, CodingKey {
            case bodyBytes = "body_bytes"
            case stringBytes = "string_bytes"
            case notesBytes = "notes_bytes"
            case screenLines = "screen_lines"
        }
    }

    enum CodingKeys: String, CodingKey {
        case serverID = "server_id"
        case serverName = "server_name"
        case protocolVersion = "protocol"
        case capabilities
        case spkiSha256 = "spki_sha256"
        case limits
        case pairingOpen = "pairing_open"
        case version
    }
}

/// What a device may do with its token.
public enum Scope: String, Codable, Sendable {
    case read
    case control
}

/// `POST /pair`.
public struct PairRequest: Encodable, Sendable {
    public let code: String
    public let deviceName: String
    public let spkiSha256: String

    public init(code: String, deviceName: String, spkiSha256: String) {
        self.code = code
        self.deviceName = deviceName
        self.spkiSha256 = spkiSha256
    }

    enum CodingKeys: String, CodingKey {
        case code
        case deviceName = "device_name"
        case spkiSha256 = "spki_sha256"
    }
}

public struct PairReply: Decodable, Sendable {
    public let token: String
    public let scope: Scope
    public let serverID: ServerID
    public let deviceID: String

    enum CodingKeys: String, CodingKey {
        case token, scope
        case serverID = "server_id"
        case deviceID = "device_id"
    }
}

/// A host's key as both ends show it to the owner for a comparison by
/// eye: the first sixteen hex digits of the SPKI hash in groups of
/// four, as the host's pairing dialog prints them.
public enum KeyFingerprint {
    public static func short(_ hex: String) -> String {
        let digits = Array(hex.prefix(16))
        return stride(from: 0, to: digits.count, by: 4)
            .map { String(digits[$0..<min($0 + 4, digits.count)]) }
            .joined(separator: " ")
    }
}

/// What the host's QR code holds while its pairing window is open: the
/// installation, the key to pin before the code is sent, the code, and
/// where the host answered from. Also pasted by hand. The host writes
/// it as the web page's URL, `https://<address>:<port>/#code=…&key=…&id=…`,
/// so a phone's browser can open the same code; an older host's JSON
/// form still parses.
public struct PairingInvite: Decodable, Sendable, Equatable {
    public let serverID: ServerID
    public let spkiSha256: String
    public let code: String
    public let addresses: [String]

    enum CodingKeys: String, CodingKey {
        case serverID = "server_id"
        case spkiSha256 = "spki_sha256"
        case code, addresses
    }

    public init(serverID: ServerID, spkiSha256: String, code: String, addresses: [String]) {
        self.serverID = serverID
        self.spkiSha256 = spkiSha256
        self.code = code
        self.addresses = addresses
    }

    /// The invite from the scanned or pasted text: the URL form, or the
    /// JSON form.
    public static func parse(_ text: String) throws -> PairingInvite {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.lowercased().hasPrefix("https://") {
            return try fromURL(trimmed)
        }
        return try Wire.decode(PairingInvite.self, from: Data(trimmed.utf8))
    }

    /// The URL form. The fragment carries `code`, `key` and `id`; the
    /// authority is the one address. Anything missing is an error, as a
    /// malformed JSON invite is.
    static func fromURL(_ text: String) throws -> PairingInvite {
        func corrupt(_ why: String) -> DecodingError {
            DecodingError.dataCorrupted(
                DecodingError.Context(codingPath: [], debugDescription: "invite URL: \(why)"))
        }
        guard let components = URLComponents(string: text), let host = components.host,
            !host.isEmpty
        else { throw corrupt("no address") }
        guard let fragment = components.fragment else { throw corrupt("no fragment") }
        var fields: [String: String] = [:]
        for pair in fragment.split(separator: "&") {
            let parts = pair.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)
            guard parts.count == 2 else { continue }
            fields[String(parts[0])] = String(parts[1]).removingPercentEncoding ?? String(parts[1])
        }
        guard let code = fields["code"], !code.isEmpty else { throw corrupt("no code") }
        guard let key = fields["key"], !key.isEmpty else { throw corrupt("no key") }
        guard let id = fields["id"], !id.isEmpty else { throw corrupt("no id") }
        let port = components.port ?? 443
        let address = host.contains(":") ? "[\(host)]:\(port)" : "\(host):\(port)"
        return PairingInvite(
            serverID: ServerID(id), spkiSha256: key.lowercased(), code: code.uppercased(),
            addresses: [address])
    }
}

