    assert_eq!(status, 200, "{reply}");
    assert_eq!(reply["body"]["projects"].as_array().unwrap().len(), 1);
    let (status, reply) = get(&mut port, "/api/v1/spaces", t);
    assert_eq!(status, 200, "{reply}");
    assert!(
        reply["body"]["spaces"]
