/// The three files are served to anyone, on the connection thread, with
/// the headers that keep the page to itself and a closed connection;
/// everything else outside the API is still the JSON 404; a query on a
/// page path is ignored and never comes back; and every JSON reply now
/// carries the browser's two headers too.
#[test]
fn the_page_is_served_to_anyone_and_the_rest_outside_the_api_is_still_json() {
    let mut port = port();
    for (path, content_type) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
    ] {
        let r = http_with(port.addr, &port.client, "GET", path, &[], "").unwrap();
        assert_eq!(r.status, 200, "{path}");
        assert_eq!(r.header("content-type"), Some(content_type), "{path}");
        assert_eq!(r.header("content-security-policy"), Some(web::CSP));
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
        assert_eq!(r.header("referrer-policy"), Some("no-referrer"));
        assert_eq!(r.header("connection"), Some("close"));
        assert_eq!(r.body, web::page(path).unwrap().body);
    }
    let r = http_with(
        port.addr,
        &port.client,
        "GET",
        "/?code=SECRETCODE&key=k",
        &[],
        "",
    )
    .unwrap();
    assert_eq!(r.status, 200);
    assert!(!r.body.contains("SECRETCODE"), "a query is not echoed");
    for (method, path) in [
        ("GET", "/favicon.ico"),
        ("POST", "/"),
        ("GET", "/api"),
        ("GET", "/index.html"),
        ("HEAD", "/app.js"),
    ] {
        let (status, reply) = call(&mut port, method, path, None, "");
        assert_eq!(
            (status, code(&reply)),
            (404, "not_found"),
            "{method} {path}: {reply}"
        );
    }
    let r = call_with(&mut port, "GET", "/api/v1/info", &[], "");
    assert_eq!(r.header("cache-control"), Some("no-store"));
    assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
    assert_eq!(r.header("content-type"), Some("application/json"));
}

/// The embedded page references only what the host serves: every `src`
/// and `href` in `index.html` is a served path or `data:`, every API
/// route in `app.js` answers a paired device with something other than
/// `not_found`, and the guards hold: no inline script or style, no
/// event attribute, no `innerHTML`.
#[test]
fn the_embedded_page_references_only_paths_the_host_serves() {
    let html = web::page("/").unwrap().body;
    let js = web::page("/app.js").unwrap().body;
    for attr in ["src=\"", "href=\""] {
        for rest in html.split(attr).skip(1) {
            let value = rest.split('"').next().unwrap();
            assert!(
                value == "data:," || web::page(value).is_some(),
                "{attr}{value} is not served"
            );
        }
    }
    assert!(!html.contains("<script>"), "no inline script");
    assert!(!html.contains("<style"), "no inline style sheet");
    assert!(!html.contains("style=\""), "no style attribute");
    let lower = html.to_ascii_lowercase();
    assert!(
        !lower
            .split(|c: char| c.is_whitespace() || c == '<')
            .any(|w| w.starts_with("on") && w.contains('=')),
        "no event attribute"
    );
    for banned in [
        "innerHTML",
        "outerHTML",
        "eval(",
        "document.write",
        "insertAdjacentHTML",
        "new Function",
    ] {
        assert!(!js.contains(banned), "{banned} in app.js");
    }

    let mut port = port();
    port.transcripts.set(Some(conversation(1)));
    let (_, project, session) = seed(&mut port, "");
    launched(&mut port, &session);
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Safari on iPhone");
    let routes: Vec<String> = js
        .match_indices("/api/v1/")
        .map(|(i, _)| js[i..].split(['\'', '"', '`']).next().unwrap().to_owned())
        .collect();
    assert!(routes.len() >= 9, "{routes:?}");
    for route in routes {
        let id = if route.contains("projects/{id}") {
            &project
        } else {
            &session
        };
        let path = route.replace("{id}", id);
        let (method, body) = if path.ends_with("/pair") || path.ends_with("/send") {
            ("POST", r#"{"op":"o1","text":"hi"}"#)
        } else {
            ("GET", "")
        };
        let (status, reply) = call(&mut port, method, &path, Some(&token), body);
        assert_ne!(
            code(&reply),
            "not_found",
            "{route} as {path}: {status} {reply}"
        );
    }
}

/// A browser pairs as the CLI does, `/info` then `/pair`, asking for its
/// token as a cookie: the reply sets `__Host-sb-<server_id>` as an
/// HttpOnly cookie and carries no token, and the cookie alone reads
/// `/me`. A native pairing is unchanged: the token in the body, no cookie.
#[test]
fn a_browser_pairs_by_cookie_and_the_cookie_alone_reads_me() {
    let mut port = port();
    let (_, info) = get(&mut port, "/api/v1/info", None);
    let spki = info["body"]["spki_sha256"].as_str().unwrap().to_owned();
    let server_id = info["body"]["server_id"].as_str().unwrap().to_owned();
    port.app.dispatch(AppAction::OpenPairing {
        code: "ABCD2345".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({
        "code": "abcd2345", "spki_sha256": spki,
        "device_name": "Safari on iPhone", "transport": "cookie",
    })
    .to_string();
    let r = call_with(&mut port, "POST", "/api/v1/pair", &[], &body);
    assert_eq!(r.status, 200, "{}", r.body);
    let reply = r.json();
    assert!(reply["body"].get("token").is_none(), "{reply}");
    assert_eq!(reply["body"]["server_id"], server_id);
    assert_eq!(reply["body"]["scope"], "read");
    let set_cookie = r.header("set-cookie").expect("Set-Cookie").to_owned();
    let (pair, attrs) = set_cookie.split_once(';').unwrap();
    let (name, token) = pair.split_once('=').unwrap();
    assert_eq!(name, format!("__Host-sb-{server_id}"));
    assert_eq!(token.len(), 43);
    let attrs: Vec<&str> = attrs.split(';').map(str::trim).collect();
    for attr in [
        "HttpOnly",
        "Secure",
        "SameSite=Strict",
        "Path=/",
        "Max-Age=34560000",
    ] {
        assert!(attrs.contains(&attr), "{attr} in {set_cookie}");
    }
    assert!(
        !attrs.iter().any(|a| a.starts_with("Domain")),
        "{set_cookie}"
    );

    let cookie = format!("{name}={token}");
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(r.status, 200, "{}", r.body);
    let me = r.json();
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_id"], server_id);
    assert_eq!(me["body"]["server_name"], info["body"]["server_name"]);
    assert_eq!(me["body"]["device_id"], reply["body"]["device_id"]);
    // Among other cookies, and on every read a token reads.
    let many = format!("theme=dark; {cookie}; other=1");
    let r = call_with(
        &mut port,
        "GET",
        "/api/v1/waiting",
        &[("Cookie", &many)],
        "",
    );
    assert_eq!(r.status, 200, "{}", r.body);
    assert_eq!(port.app.core().devices()[0].name, "Safari on iPhone");
    // The bearer header still reads nothing without a token.
    let (status, reply) = get(&mut port, "/api/v1/me", None);
    assert_eq!((status, code(&reply)), (401, "unauthorized"));

    port.app.dispatch(AppAction::OpenPairing {
        code: "BCDE3456".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({
        "code": "BCDE3456", "spki_sha256": spki, "device_name": "Vision Pro",
    })
    .to_string();
    let r = call_with(&mut port, "POST", "/api/v1/pair", &[], &body);
    assert_eq!(r.status, 200, "{}", r.body);
    let native = r.json();
    assert_eq!(native["body"]["token"].as_str().unwrap().len(), 43);
    assert!(
        r.header("set-cookie").is_none(),
        "no cookie for a native client"
    );
    let (status, me) = get(
        &mut port,
        "/api/v1/me",
        Some(native["body"]["token"].as_str().unwrap()),
    );
    assert_eq!(status, 200, "{me}");
    assert_eq!(me["body"]["name"], "Vision Pro");
}

/// Two instances on one Mac share one address, so a browser's cookie
/// jar holds both their cookies: each is named for its server id, each
/// host reads only its own, and the fixed name authenticates nothing.
#[test]
fn two_hosts_set_differently_named_cookies_and_each_reads_only_its_own() {
    let mut a = port();
    let mut b = port();
    let ca = pair_by_cookie(&mut a, "ABCD2345", Scope::Read, "Safari on iPhone");
    let cb = pair_by_cookie(&mut b, "ABCD2345", Scope::Read, "Safari on iPhone");
    assert_ne!(ca.name, cb.name);
    assert!(ca.name.starts_with("__Host-sb-"));
    let both = format!("{}; {}", ca.pair(), cb.pair());
    let r = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &both)], "");
    assert_eq!(r.status, 200, "{}", r.body);
    assert_eq!(r.json()["body"]["device_id"], ca.device_id);
    let r = call_with(&mut b, "GET", "/api/v1/me", &[("Cookie", &both)], "");
    assert_eq!(r.status, 200, "{}", r.body);
    assert_eq!(r.json()["body"]["device_id"], cb.device_id);
    // Only the other host's cookie: a stranger.
    let r = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &cb.pair())], "");
    assert_eq!((r.status, code(&r.json())), (401, "unauthorized"));
    let r = call_with(&mut b, "GET", "/api/v1/me", &[("Cookie", &ca.pair())], "");
    assert_eq!((r.status, code(&r.json())), (401, "unauthorized"));
    // The fixed name, with a valid token under it.
    let fixed = format!("__Host-sb={}", ca.token);
    let r = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &fixed)], "");
    assert_eq!((r.status, code(&r.json())), (401, "unauthorized"));
}

/// A write authenticated by the cookie alone must come from the page's
/// own origin (`https://` and the `Host` header): without an `Origin`
/// or with another, 403 `origin`; a `GET` needs none; a bearer request
/// needs none; and the same holds for the upgrade to the events socket.
#[test]
fn a_cookie_write_needs_the_pages_origin_and_a_bearer_needs_none() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let cookie = pair_by_cookie(&mut port, "ABCD2345", Scope::Control, "Chrome on Android");
    let token = pair(&mut port, "BCDE3456", Scope::Control, "Pad");
    let send = format!("/api/v1/sessions/{session}/send");
    let c = cookie.pair();
    let body = |op: &str| serde_json::json!({ "op": op, "text": "hello" }).to_string();
    let r = call_with(&mut port, "POST", &send, &[("Cookie", &c)], &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let other_port = [("Cookie", c.as_str()), ("Origin", "https://localhost:1")];
    let r = call_with(&mut port, "POST", &send, &other_port, &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let elsewhere = [("Cookie", c.as_str()), ("Origin", "https://evil.example")];
    let r = call_with(&mut port, "POST", &send, &elsewhere, &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let own = [("Cookie", c.as_str()), ("Origin", "https://localhost")];
    let r = call_with(&mut port, "POST", &send, &own, &body("o1"));
    assert_ne!(code(&r.json()), "origin", "{}", r.body);
    assert_ne!(r.status, 403, "{}", r.body);
    let r = call_with(&mut port, "GET", "/api/v1/waiting", &[("Cookie", &c)], "");
    assert_eq!(r.status, 200, "a read needs no Origin: {}", r.body);
    let (status, reply) = call(&mut port, "POST", &send, Some(&token), &body("o2"));
    assert_ne!(code(&reply), "origin", "{status} {reply}");
    assert_ne!(status, 403, "{reply}");

    let foreign = subscribe_with(
        &mut port,
        vec![
            ("Cookie".into(), c.clone()),
            ("Origin".into(), "https://evil.example".into()),
        ],
        "/api/v1/events",
    );
    assert!(foreign.is_err(), "a foreign upgrade is refused");
    let bare = subscribe_with(
        &mut port,
        vec![("Cookie".into(), c.clone())],
        "/api/v1/events",
    );
    assert!(bare.is_err(), "an upgrade with no Origin is refused");
    let own = subscribe_with(
        &mut port,
        vec![
            ("Cookie".into(), c),
            ("Origin".into(), "https://localhost".into()),
        ],
        "/api/v1/events",
    );
    assert!(own.is_ok(), "{:?}", own.err());
    assert_eq!(port.app.subscriber_count(), 1);
}

/// `/me` says the device's scope as the dialog sets it; after Revoke
/// the cookie is the same 401 as an unknown token and `/info` still
/// names the same host, which is what lets the page say "removed".
#[test]
fn me_follows_the_scope_and_a_revoked_cookie_is_refused_while_info_is_unchanged() {
    let mut port = port();
    let cookie = pair_by_cookie(&mut port, "ABCD2345", Scope::Read, "Safari on iPad");
    let (_, before) = get(&mut port, "/api/v1/info", None);
    let c = cookie.pair();
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!(r.json()["body"]["scope"], "read");
    let device = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::SetDeviceScope {
        device,
        scope: Scope::Control,
    });
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!(r.json()["body"]["scope"], "control");
    port.app.dispatch(AppAction::RevokeDevice(device));
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!((r.status, code(&r.json())), (401, "unauthorized"));
    let (_, after) = get(&mut port, "/api/v1/info", None);
    assert_eq!(after["body"]["server_id"], before["body"]["server_id"]);
    assert_eq!(after["body"]["spki_sha256"], before["body"]["spki_sha256"]);
}

/// A page reply closes its connection, so loads in a row never hold
/// the pool; five at once against a pool of four are measured; and the
/// page has a window of its own, 120 a minute, which leaves `/info` and
/// `/pair` theirs.
#[test]
fn page_loads_free_their_slot_and_have_their_own_window() {
    let first = port();
    for _ in 0..=MAX_UNAUTHENTICATED {
        let r = http_with(first.addr, &first.client, "GET", "/app.css", &[], "").unwrap();
        assert_eq!(r.status, 200);
    }
    let served = (0..5)
        .map(|_| {
            let addr = first.addr;
            let config = Arc::clone(&first.client);
            std::thread::spawn(move || {
                http_with(addr, &config, "GET", "/app.js", &[], "").is_ok_and(|r| r.status == 200)
            })
        })
        .collect::<Vec<_>>()
        .into_iter()
        .filter_map(|t| t.join().unwrap().then_some(()))
        .count();
    eprintln!("parallel page requests served: {served} of 5 against a pool of 4");
    assert!(served >= MAX_UNAUTHENTICATED, "{served}");
    drop(first);

    let mut port = port();
    for n in 0..PAGE_PER_MINUTE {
        let r = http_with(port.addr, &port.client, "GET", "/", &[], "").unwrap();
        assert_eq!(r.status, 200, "page request {n}");
    }
    let r = http_with(port.addr, &port.client, "GET", "/app.js", &[], "").unwrap();
    assert_eq!((r.status, code(&r.json())), (429, "rate_limited"));
    let (status, _) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200, "info has its own window");
    let (status, reply) = call(&mut port, "POST", "/api/v1/pair", None, "{}");
    assert_eq!(
        (status, code(&reply)),
        (403, "pairing_closed"),
        "pair has its own window"
    );
}

