    let plain = subscribe(&mut port, &token);
    let all = subscribe_at(&mut port, &token, "/api/v1/events?scope=all");
    for (id, name) in [
        (&reviewer, "reviewer 2"),
        (&planner, "planner 2"),
        (&supervisor, "Supervisor 2"),
        (&session, "investigator 2"),
    ] {
